// See docs/SPEC.md.

const NUM = '(?:0|[1-9]\\d*)';
const IDENT = '[0-9A-Za-z-]+';
const DOTTED = `${IDENT}(?:\\.${IDENT})*`;
const PRE_BUILD = `(?:-(${DOTTED}))?(?:\\+${DOTTED})?`;
const VERSION_RE = new RegExp(`^v?(${NUM})\\.(${NUM})\\.(${NUM})${PRE_BUILD}$`);
// A partial version: each position is a number or a wildcard; a prerelease only after a full version.
const PART = `(${NUM}|[xX*])`;
const PARTIAL_RE = new RegExp(`^v?${PART}(?:\\.${PART}(?:\\.${PART}${PRE_BUILD})?)?$`);
const OPERATORS = ['<', '<=', '>', '>=', '='];

function toInt(s) {
  const n = Number(s);
  return Number.isSafeInteger(n) ? n : null;
}

function makeVersion(major, minor, patch, pre) {
  return { major, minor, patch, pre: pre ? pre.split('.') : [] };
}

function parseVersion(str) {
  const m = VERSION_RE.exec(str.trim());
  if (!m) return null;
  const nums = [m[1], m[2], m[3]].map(toInt);
  if (nums.includes(null)) return null;
  return makeVersion(...nums, m[4]);
}

// Returns { nums: [major?, minor?, patch?], pre } where nums holds only the
// leading non-wildcard positions, or null when invalid.
function parsePartial(str) {
  const m = PARTIAL_RE.exec(str);
  if (!m) return null;
  const nums = [];
  let wild = false;
  for (const part of [m[1], m[2], m[3]]) {
    const isWild = part === undefined || /^[xX*]$/.test(part);
    if (isWild) wild = true;
    else if (wild) return null; // a number after a wildcard, e.g. `1.x.3`
    else {
      const n = toInt(part);
      if (n === null) return null;
      nums.push(n);
    }
  }
  if (m[4] !== undefined && nums.length < 3) return null;
  return { nums, pre: m[4] };
}

function compareIdent(a, b) {
  const an = /^\d+$/.test(a);
  const bn = /^\d+$/.test(b);
  if (an && bn) {
    // Compare as big integers without precision loss.
    const x = a.replace(/^0+(?=.)/, '');
    const y = b.replace(/^0+(?=.)/, '');
    if (x.length !== y.length) return x.length < y.length ? -1 : 1;
    return x < y ? -1 : x > y ? 1 : 0;
  }
  if (an) return -1;
  if (bn) return 1;
  return a < b ? -1 : a > b ? 1 : 0;
}

function compare(a, b) {
  for (const k of ['major', 'minor', 'patch']) {
    if (a[k] !== b[k]) return a[k] < b[k] ? -1 : 1;
  }
  if (!a.pre.length || !b.pre.length) return b.pre.length - a.pre.length && (a.pre.length ? -1 : 1);
  for (let i = 0; i < Math.min(a.pre.length, b.pre.length); i++) {
    const c = compareIdent(a.pre[i], b.pre[i]);
    if (c) return c;
  }
  return Math.sign(a.pre.length - b.pre.length);
}

const NOTHING = [{ op: '<', version: makeVersion(0, 0, 0) }]; // nothing is below 0.0.0
const ANY = [];

const ge = (version) => ({ op: '>=', version });
const lt = (version) => ({ op: '<', version });

// Filled-in lower bound of a partial with at least one number: missing positions are zeros.
function floor({ nums, pre }) {
  return makeVersion(nums[0], nums[1] || 0, nums[2] || 0, pre);
}

// Smallest version above everything matched by a partial with 1 or 2 numbers.
function ceiling({ nums }) {
  return nums.length === 1 ? makeVersion(nums[0] + 1, 0, 0) : makeVersion(nums[0], nums[1] + 1, 0);
}

// Desugars `op` + partial into a list of primitive comparators.
function desugar(op, p) {
  const n = p.nums.length;
  const full = n === 3 ? floor(p) : null;
  const [M, m, pt] = p.nums;
  switch (op) {
    case '':
    case '=':
      if (n === 0) return ANY;
      if (full) return [{ op: '=', version: full }];
      return [ge(floor(p)), lt(ceiling(p))];
    case '>':
      if (n === 0) return NOTHING;
      return full ? [{ op: '>', version: full }] : [ge(ceiling(p))];
    case '>=':
      return n === 0 ? ANY : [ge(floor(p))];
    case '<':
      return n === 0 ? NOTHING : [lt(floor(p))];
    case '<=':
      if (n === 0) return ANY;
      return full ? [{ op: '<=', version: full }] : [lt(ceiling(p))];
    case '~':
      if (n === 0) return ANY;
      return [ge(floor(p)), lt(n === 1 ? makeVersion(M + 1, 0, 0) : makeVersion(M, m + 1, 0))];
    case '^': {
      if (n === 0) return ANY;
      let upper;
      if (M > 0 || n === 1) upper = makeVersion(M + 1, 0, 0);
      else if (m > 0 || n === 2) upper = makeVersion(0, m + 1, 0);
      else upper = makeVersion(0, 0, pt + 1);
      return [ge(floor(p)), lt(upper)];
    }
    default:
      return null;
  }
}

function hyphen(a, b) {
  const result = [];
  if (a.nums.length) result.push(ge(floor(a)));
  if (b.nums.length === 3) result.push({ op: '<=', version: floor(b) });
  else if (b.nums.length) result.push(lt(ceiling(b)));
  return result;
}

// Parses one comparator set into a list of primitive comparators, or null when invalid.
function parseSet(str) {
  const tokens = str.trim().split(/\s+/).filter(Boolean);
  const result = [];
  for (let i = 0; i < tokens.length; i++) {
    if (tokens[i + 1] === '-') {
      const a = parsePartial(tokens[i]);
      const b = tokens[i + 2] === undefined ? null : parsePartial(tokens[i + 2]);
      if (!a || !b) return null;
      result.push(...hyphen(a, b));
      i += 2;
      continue;
    }
    let token = tokens[i];
    if (OPERATORS.includes(token)) {
      if (tokens[i + 1] === undefined) return null;
      token += tokens[++i];
    }
    const [, op, rest] = /^(<=|>=|<|>|=|~|\^)?(.*)$/.exec(token);
    const p = parsePartial(rest);
    if (!p) return null;
    result.push(...desugar(op || '', p));
  }
  return result;
}

function test(version, { op, version: other }) {
  const c = compare(version, other);
  switch (op) {
    case '<': return c < 0;
    case '<=': return c <= 0;
    case '>': return c > 0;
    case '>=': return c >= 0;
    case '=': return c === 0;
  }
  return false;
}

function satisfiesSet(version, set) {
  if (!set.every((c) => test(version, c))) return false;
  if (!version.pre.length) return true;
  return set.some(({ version: v }) => v.pre.length
    && v.major === version.major && v.minor === version.minor && v.patch === version.patch);
}

function satisfies(version, range) {
  try {
    if (typeof version !== 'string' || typeof range !== 'string') return false;
    const v = parseVersion(version);
    if (!v) return false;
    const sets = range.split('||').map(parseSet);
    if (sets.includes(null)) return false;
    return sets.some((set) => satisfiesSet(v, set));
  } catch {
    return false;
  }
}

module.exports = { satisfies };

